#include <cstddef>
#include <format>
#include <iostream>
#include <span>

struct Quote {
    char side;
    int quantity;
};

void dump_bytes(std::span<const std::byte> bytes) {
    for (std::byte byte : bytes) {
        std::cout << std::format("{:02x} ",
                                 std::to_integer<unsigned int>(byte));
    }
    std::cout << '\n';
}

// std::memcmp compares the whole object representation, including the three
// padding bytes between side and quantity. Member assignment does not promise
// anything about those bytes, so equal values can compare unequal.
bool value_equal(const Quote& left, const Quote& right) {
    return left.side == right.side && left.quantity == right.quantity;
}

#include <cstddef>

struct Fill {
    char side;      // 0        (+7 padding)
    double price;   // 8 - 15
    int quantity;   // 16 - 19
    short venue;    // 20 - 21  (+2 tail padding)
};

static_assert(alignof(Fill) == 8);
static_assert(sizeof(Fill) == 24);

struct FillCompact {
    double price;   // 0 - 7
    int quantity;   // 8 - 11
    short venue;    // 12 - 13
    char side;      // 14      (+1 tail padding)
};

static_assert(alignof(FillCompact) == 8);
static_assert(sizeof(FillCompact) == 16);

// 8 bytes saved per element: an array of 1,000,000 fills shrinks by 8 MB,
// and each 64-byte cache line now holds 4 fills instead of 2.

#include <cstddef>
#include <functional>

template<class Compare>
class SortedBook {
public:
    SortedBook() = default;

    bool improves(double candidate) const {
        return compare_(candidate, best_price_);
    }

    void set_best(double price) { best_price_ = price; }

private:
    [[no_unique_address]] Compare compare_{};
    double best_price_ = 0.0;
};

struct Less {
    bool operator()(double a, double b) const { return a < b; }
};

// A stateless comparator is allowed to overlap best_price_, so the wrapper
// costs exactly what the payload costs. Give Compare a data member and every
// SortedBook in every array grows -- keep this assertion beside the class.
static_assert(sizeof(SortedBook<Less>) == sizeof(double));
static_assert(sizeof(SortedBook<std::less<double>>) == sizeof(double));

#include <cstddef>
#include <cstdint>
#include <type_traits>

struct Tick {
    std::int64_t timestamp;
    double price;
    std::int32_t quantity;
    std::int32_t venue;
};

// Licenses std::memcpy between live Ticks and a byte-buffer round trip.
static_assert(std::is_trivially_copyable_v<Tick>);

// Licenses offsetof and the common-initial-sequence and C-interop rules.
static_assert(std::is_standard_layout_v<Tick>);

// Licenses Tick tick{} costing nothing beyond the stores you asked for.
static_assert(std::is_trivial_v<Tick>);

// Pins the layout this translation target agreed to.
static_assert(sizeof(Tick) == 24);
static_assert(alignof(Tick) == 8);
static_assert(offsetof(Tick, price) == 8);
static_assert(offsetof(Tick, quantity) == 16);
static_assert(offsetof(Tick, venue) == 20);

// These assertions describe a native object copy, not a portable wire format:
// padding, byte order and floating-point encoding are still ABI-specific.

#include <cstdint>
#include <type_traits>

struct Add {
    int kind;
    int quantity;
};

struct Cancel {
    int kind;
    std::uint64_t order_id;
};

static_assert(std::is_standard_layout_v<Add>);
static_assert(std::is_standard_layout_v<Cancel>);

union Message {
    Add add;
    Cancel cancel;
};

// The common initial sequence is exactly `kind`: corresponding initial members
// with layout-compatible types. Reading it through either alternative is
// permitted no matter which one is active.
int inspect_kind(const Message& message) {
    return message.cancel.kind;
}

int quantity_of(const Message& message) {
    // Precondition: add is the active alternative. Reading message.cancel
    // .order_id here would be undefined behaviour -- order_id is past the
    // end of the common initial sequence.
    return message.add.quantity;
}

// Without a C ABI requirement, std::variant<Add, Cancel> tracks the active
// alternative for you and turns the mistake above into a checked access.

#include <bit>
#include <cstdint>
#include <cstring>
#include <type_traits>

static_assert(sizeof(float) == sizeof(std::uint32_t));
static_assert(std::is_trivially_copyable_v<float>);

std::uint32_t bits_with_memcpy(float value) {
    std::uint32_t result;
    std::memcpy(&result, &value, sizeof(result));
    return result;
}

constexpr std::uint32_t bits_with_bit_cast(float value) {
    return std::bit_cast<std::uint32_t>(value);
}

constexpr float float_from_bits(std::uint32_t image) {
    return std::bit_cast<float>(image);
}

static_assert(float_from_bits(bits_with_bit_cast(1.0F)) == 1.0F);

// *reinterpret_cast<std::uint32_t*>(&value) is undefined behaviour at the
// dereference, not at the cast: the float object is being accessed through a
// type outside its permitted alias set. It usually works at -O0 and changes
// once alias analysis and inlining run at -O2.

#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>

static_assert(std::endian::native == std::endian::little ||
              std::endian::native == std::endian::big);

std::uint32_t read_be32(std::span<const std::byte, 4> bytes) {
    std::uint32_t value;
    std::memcpy(&value, bytes.data(), sizeof(value));
    if constexpr (std::endian::native == std::endian::little) {
        value = std::byteswap(value);
    }
    return value;
}

// std::byteswap is defined for integers only, and "reversing a float" is not a
// meaningful numeric operation. Correct the representation as an integer of the
// same size, then reinterpret the corrected bits. This still assumes both ends
// use IEEE-754 binary32: byte order cannot bridge different numeric formats.
float read_be_float(std::span<const std::byte, 4> bytes) {
    return std::bit_cast<float>(read_be32(bytes));
}

#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>
#include <stdexcept>
#include <type_traits>

struct MdTrade {
    std::uint64_t sequence;
    std::uint32_t price;
    std::uint16_t quantity;
    std::byte side;
    std::byte reserved;
};

static_assert(std::is_trivially_copyable_v<MdTrade>);
static_assert(std::is_standard_layout_v<MdTrade>);
static_assert(sizeof(MdTrade) == 16);
static_assert(alignof(MdTrade) == 8);
static_assert(offsetof(MdTrade, sequence) == 0);
static_assert(offsetof(MdTrade, price) == 8);
static_assert(offsetof(MdTrade, quantity) == 12);
static_assert(offsetof(MdTrade, side) == 14);
static_assert(offsetof(MdTrade, reserved) == 15);

MdTrade parse_trade(std::span<const std::byte> buffer) {
    if (buffer.size() < sizeof(MdTrade)) {
        throw std::invalid_argument{"short trade message"};
    }

    // memcpy into a real, correctly aligned MdTrade. The buffer holds byte
    // objects, not a live MdTrade, and its address need not be 8-byte aligned.
    MdTrade message;
    std::memcpy(&message, buffer.data(), sizeof(message));

    if constexpr (std::endian::native == std::endian::little) {
        message.sequence = std::byteswap(message.sequence);
        message.price = std::byteswap(message.price);
        message.quantity = std::byteswap(message.quantity);
        // side and reserved are single bytes: byte order does not apply.
    }
    return message;
}
